import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Kırpma, fotoğrafı düzeltmenin en hızlı yoludur. İstenmeyen kenarları atar, konuyu öne çıkarır ve görseli hedef boyuta getirir.</p>\n<p>İyi bir kırpma, fotoğrafı yeniden çeker. Kötü bir kırpma ise önemli ayrıntıyı keser ve görseli bozar.</p>\n<p>Bu kılavuz, kırpmanın ne yaptığını, oranların nasıl seçildiğini ve profil fotoğrafı, afiş ile baskı için hangi kırpmanın işe yaradığını anlatıyor.</p>\n<h2 id=\"what-cropping-does\">Kırpma gerçekte ne yapar?</h2>\n<p>Kırpma, görselin bir kısmını atar. Seçilen alan kalır; geri kalan silinir.</p>\n<p>Kırpma, konuyu öne çıkarır. Dikkat dağıtan kenarlar gider; göz konuya odaklanır.</p>\n<p>Kırpma, oranı değiştirir. Yatay fotoğraf kareye, kare fotoğraf dikey biçime döner.</p>\n<h2 id=\"aspect-ratios-explained\">Oranlar: kırpmanızın biçimi</h2>\n<p>Oran, genişliğin yüksekliğe oranıdır. 1:1 kare, 16:9 geniş ekran demektir.</p>\n<p>Her platform kendi oranını ister. Profil fotoğrafı kare, kapak görseli geniş ister.</p>\n<p>Oranı baştan seçin. Yanlış oran, sonradan düzeltmesi zor kırpmaya yol açar.</p>\n<h2 id=\"rule-of-thirds\">Üçte bir kuralı ve kırpma ızgarası</h2>\n<p>Üçte bir kuralı, konuyu ızgara çizgilerinin kesişimine koymaktır. Bu, fotoğrafı dengeli gösterir.</p>\n<p>Kırpma aracındaki ızgara, bu kuralı uygular. Konuyu çizgilerin kesişimine sürükleyin.</p>\n<p>Kuralı her zaman izlemek zorunda değilsiniz. Merkezdeki konu da güçlü olabilir; ızgara yalnızca rehberdir.</p>\n<h2 id=\"zoom-and-precise-framing\">Yakınlaştırma ve hassas çerçeveleme</h2>\n<p>Yakınlaştırma, küçük ayrıntıyı tam kırpmanızı sağlar. Yüzü ya da ürünü tam çerçeveye alın.</p>\n<p>Yakınlaştırırken çözünürlüğe dikkat edin. Fazla yakınlaştırma, pikselleri büyütür ve bulanıklık yapar.</p>\n<p>Hassas çerçeve için ızgarayı kullanın. Çizgiler, konunun nereye oturduğunu gösterir.</p>\n<h2 id=\"crop-quality-and-formats\">Kalite, formatlar ve korunanlar</h2>\n<p>Kırpma kalite kaybettirmez. Kalan pikseller orijinal kalitededir; yalnızca alan küçülür.</p>\n<p>Çıktı formatı önemlidir. Fotoğraflar için JPG, saydam görseller için PNG kullanın.</p>\n<p>Küçük kırpma, düşük çözünürlük demektir. Hedef boyuta yetecek kadar piksel bırakın.</p>\n<h2 id=\"cropping-for-profiles\">Profil fotoğrafı ve avatar için kırpma</h2>\n<p>Profil fotoğrafları kare ister. Yüzü merkeze alın ve başın üstünde biraz boşluk bırakın.</p>\n<p>Yüzü çok yakın kırpmayın. Platform, kareyi daireye çevirir; köşeler kesilir.</p>\n<p>Yüksek çözünürlüklü kaynak kullanın. Küçük kaynaktan kırpılan avatar bulanık görünür.</p>\n<h2 id=\"cropping-for-social-media\">Sosyal medya ve afiş için kırpma</h2>\n<p>Her platform kendi boyutunu ister. Kapak görseli, gönderi ve hikâye farklı oranlardadır.</p>\n<p>Platform kurallarını öğrenin. Yanlış oran, görselin otomatik kırpılmasına yol açar.</p>\n<p>Önemli öğeleri merkeze koyun. Kenarlar, platformda kesilebilir.</p>\n<h2 id=\"cropping-documents-and-screenshots\">Belge ve ekran görüntüsü kırpma</h2>\n<p>Belgelerde kenar boşluklarını atın. Tarama kenarındaki gölgeler ve lekeler gider.</p>\n<p>Ekran görüntülerinde gereksiz araç çubuklarını kırpın. Yalnızca ilgili bölüm kalmalıdır.</p>\n<p>Yazıları kesmemeye dikkat edin. Kırpma çizgisi, metnin üzerinden geçmemelidir.</p>\n<h2 id=\"crop-before-compress\">Önce kırpın, sonra sıkıştırın</h2>\n<p>Kırpma, dosya boyutunu küçültür. Atılan pikseller sıkıştırılmaz; dosya baştan hafifler.</p>\n<p>Önce kırpıp sonra sıkıştırmak, daha iyi kalite verir. Sıkıştırıcı, yalnızca kalan pikselleri işler.</p>\n<p>Sıralama önemlidir. Önce kırpın, sonra boyutlandırın, en son sıkıştırın.</p>\n<h2 id=\"privacy-and-cropping\">Gizlilik: kırpma pikselden fazlasını atar</h2>\n<p>Kırpma, arka plandaki kişisel ayrıntıyı atar. Adres, plaka ve yüzler kırpmayla gider.</p>\n<p>Ancak kırpma, meta veriyi silmez. Konum bilgisi dosyada kalır; ayrıca silinmelidir.</p>\n<p>Paylaşmadan önce kırpılan alanı kontrol edin. Gizli ayrıntı kalmadığından emin olun.</p>\n<h2 id=\"common-crop-mistakes\">Kırparken yaygın hatalar</h2>\n<p>En yaygın hata, çok dar kırpmaktır. Konu çerçeveye sığmaz ve fotoğraf boğulur.</p>\n<p>Bir başka hata, orijinali silmektir. Kırpma geri alınamaz; orijinali saklayın.</p>\n<p>Üçüncü hata, yanlış orandır. Hedef platformun oranını öğrenmeden kırpmayın.</p>\n<h2 id=\"crop-workflow-tips\">Kırpmaları temiz tutan bir akış</h2>\n<p>Önce hedefi belirleyin. Profil mi, afiş mi, baskı mı? Hedef, oranı belirler.</p>\n<p>Sonra çerçeveyi ayarlayın. Izgara ve oran ön ayarlarını kullanın.</p>\n<p>Son olarak indirmeden önce kontrol edin. Önizlemede konunun tam göründüğünü doğrulayın.</p>\n<h2 id=\"cropping-group-photos\">Grup fotoğraflarını kırpmak</h2>\n<p>Grup fotoğraflarında herkesi çerçeveye alın. Kimseyi yarıda kesmeyin.</p>\n<p>Kenardaki kişileri kontrol edin. Kırpma çizgisi, kimsenin yüzünden geçmemelidir.</p>\n<p>Grup fotoğrafını kareye zorlamayın. Geniş oran, grup için daha doğrudur.</p>\n<h2 id=\"cropping-for-print\">Baskı için kırpma</h2>\n<p>Baskı için oran, kâğıt boyutuna uymalıdır. 10x15 baskı, 3:2 oran ister.</p>\n<p>Baskıda çözünürlük kritiktir. 300 DPI hedefleyin; küçük kırpma baskıda bulanık çıkar.</p>\n<p>Baskı merkezine sormaktan çekinmeyin. Hangi oranı istediklerini öğrenmek, boşa giden baskıyı önler.</p>\n<h2 id=\"cropping-vs-resizing\">Kırpma ve boyutlandırma: hangisi gerekli?</h2>\n<p>Kırpma alanı değiştirir; boyutlandırma piksel sayısını değiştirir. İki işlem farklıdır.</p>\n<p>Oran yanlışsa kırpın. Boyut büyükse boyutlandırın; ikisi birlikte de yapılabilir.</p>\n<p>Önce kırpın, sonra boyutlandırın. Sıralama, gereksiz işi önler.</p>\n<h2 id=\"cropping-and-file-size\">Kırpma ve dosya boyutu</h2>\n<p>Kırpma, dosyayı küçültür. Atılan pikseller artık dosyada değildir.</p>\n<p>Yarıya kırpılan fotoğraf, yarı boyutunda olur. Bu, sıkıştırmadan önce gelen bedava kazançtır.</p>\n<p>Küçük kırpma, küçük dosya demektir. Ancak çözünürlük hedefe yetmelidir.</p>\n<p>Özetle: önce hedefi belirleyin, sonra kırpın. Adımlar için <a href=\"/tr/blog/gorsel-nasil-kirpilir\">Görsel kırpma nasıl yapılır</a> yazısına bakın; oranlar için <a href=\"/tr/blog/gorsel-kirp-oranlari-aciklandi\">görsel kırpma oranları</a> yazısı yardımcı olur. Bulanıklaştırma için <a href=\"/tr/gorsel-bulaniklastir-piksellestir\">bulanıklaştırma ve pikselleştirme</a>, köşeler için <a href=\"/tr/gorsel-kose-yuvarla\">köşe yuvarlama</a> hazırdır; araç ise <a href=\"/tr/gorsel-kirp\">görsel kırpıcı</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Profil fotoğrafı için en iyi oran hangisi?","answer":"1:1 kare oran en iyisidir. Yüzü merkeze alın ve başın üstünde biraz boşluk bırakın. Platform, kareyi daireye çevirir; köşeler kesilir, bu yüzden önemli öğeleri merkeze koyun."},{"question":"Görsel kırpmak kaliteyi düşürür mü?","answer":"Hayır. Kırpma kalite kaybettirmez; kalan pikseller orijinal kalitededir, yalnızca alan küçülür. Ancak çok dar kırpma, düşük çözünürlük demektir; hedef boyuta yetecek kadar piksel bırakın."},{"question":"Facebook kapağı ya da web afişi için fotoğrafı nasıl kırparım?","answer":"Platformun istediği oranı öğrenin; kapak görselleri genellikle geniş oran ister. Önemli öğeleri merkeze koyun, kenarlar kesilebilir. Önizlemede sonucun tam göründüğünü doğrulayın."},{"question":"Telefonumda ekran görüntüsünü kırpabilir miyim?","answer":"Evet. Kırpma aracını telefon tarayıcısında açın, ekran görüntüsünü yükleyin ve seçim kutusunu sürükleyin. Gereksiz araç çubuklarını kırpın; yalnızca ilgili bölüm kalsın."},{"question":"Görseli sıkıştırmadan önce mi sonra mı kırpmalıyım?","answer":"Önce kırpın. Kırpma, dosya boyutunu küçültür ve sıkıştırıcı yalnızca kalan pikselleri işler; bu daha iyi kalite verir. Sıralama: önce kırpın, sonra boyutlandırın, en son sıkıştırın."},{"question":"Kırpmamın hedefi için yeterince büyük olduğunu nasıl anlarım?","answer":"Çıktı boyutlarını indirmeden önce kontrol edin. Hedef platformun istediği piksel boyutuyla karşılaştırın; kırpılan alan hedeften küçükse kaynak fotoğraf yetersizdir. Daha yüksek çözünürlüklü kaynak kullanın."}];
